fl_value_t fl_vm_call(fl_vm_t* vm, fl_value_t func, fl_value_t* args, size_t arg_count) {
    (void)func;
    (void)args;
    (void)arg_count;

    fl_value_t null_val;
    null_val.type = FL_TYPE_NULL;
    return null_val;
}

