      i = i + 1
      continue
    }
    if (ch == "=" && i + 1 < len && source[i + 1] == "=") {
      push(tokens, [19, "=="])
      i = i + 2
      continue
    }
    if (ch == "=") {
      push(tokens, [14, "="])
      i = i + 1
      continue
    }
    if (ch == "!") {
      if (i + 1 < len && source[i + 1] == "=") {
        push(tokens, [20, "!="])
        i = i + 2
      } else {
        i = i + 1
      }
      continue
    }
    if (ch == "<" && i + 1 < len && source[i + 1] == "=") {
      push(tokens, [22, "<="])
      i = i + 2
      continue
    }
    if (ch == "<") {
      push(tokens, [21, "<"])
      i = i + 1
      continue
    }
    if (ch == ">" && i + 1 < len && source[i + 1] == "=") {
      push(tokens, [24, ">="])
      i = i + 2
      continue
    }
    if (ch == ">") {
      push(tokens, [23, ">"])
      i = i + 1
      continue
    }
    if (ch == "+") {
      push(tokens, [15, "+"])
      i = i + 1
      continue
    }
    if (ch == "-") {
      push(tokens, [16, "-"])
      i = i + 1
      continue
    }
    if (ch == "*") {
      push(tokens, [17, "*"])
      i = i + 1
      continue
    }
    if (ch == "/") {
      push(tokens, [18, "/"])
      i = i + 1
      continue
    }

    /* 알 수 없는 문자 스킵 */
    i = i + 1
  }

  push(tokens, [0, ""])  /* EOF */
  return tokens
}

/* ============================================================
   Main: 렉서 테스트
   ============================================================ */

fn main() {
  println("=======================================")
  println("FreeLang Lexer - Phase 2.1")
  println("=======================================")

  let source = read_file("hello.free")
  println("Source code loaded")

  let tokens = tokenize(source)
  println("Tokenization complete")

  let i = 0
  let count = 0
  while (i < len(tokens) && count < 20) {
    let token = tokens[i]
    let type_id = token[0]
    let value = token[1]
    println(token_type_string(type_id))
    i = i + 1
    count = count + 1
  }

  println("=======================================")
  println("Total tokens: ")
  println(len(tokens))
  println("=======================================")
}

main()

